import React from "react";
import { useCart } from "../comPoNent/GioHang/CartContext";
import "bootstrap/dist/css/bootstrap.min.css";

const HomePage = () => {
    const { addToCart } = useCart();

    const categories = [
        { name: "Đồ nam", image: "/assets/doNam.jpg" },
        { name: "Áo thun nam", image: "/assets/AoThun.jpg" },
        { name: "Áo hoodie nam", image: "/assets/AoHodie.jpg" },
        { name: "Đồ nữ", image: "/assets/doNu.jpg" }
    ];

    const products = [
        { id: 1, name: "Sản phẩm 1", price: 250000, image: "/assets/product1.jpg" },
        { id: 2, name: "Sản phẩm 2", price: 300000, image: "/assets/product2.jpg" },
        { id: 3, name: "Sản phẩm 3", price: 200000, image: "/assets/product3.jpg" },
        { id: 4, name: "Sản phẩm 4", price: 400000, image: "/assets/product4.jpg" },
        { id: 5, name: "Sản phẩm 5", price: 350000, image: "/assets/product5.jpg" }
    ];

    return (
        <div className="container mt-4">
            {/* Danh mục nổi bật */}
            <div className="text-center mb-5">
                <h2 className="fw-bold">DANH MỤC NỔI BẬT</h2>
                <div className="row mt-4">
                    {categories.map((cat, idx) => (
                        <div key={idx} className="col-md-3 mb-3">
                            <div className="card h-100 shadow-sm">
                                <img src={cat.image} className="card-img-top" alt={cat.name} />
                                <div className="card-body text-center">
                                    <h5 className="card-title">{cat.name}</h5>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Bộ lọc và sản phẩm */}
            <div className="row">
                {/* Bộ lọc */}
                <div className="col-md-3 mb-4">
                    <div className="border rounded p-3 bg-light">
                        <h5>Chọn khoảng giá</h5>
                        <input type="number" className="form-control mb-2" placeholder="Từ" />
                        <input type="number" className="form-control mb-2" placeholder="Đến" />
                        <button className="btn btn-primary w-100 mb-3">Áp dụng</button>

                        <h5>Chọn danh mục</h5>
                        <div className="form-check">
                            <input className="form-check-input" type="checkbox" id="nam" />
                            <label className="form-check-label" htmlFor="nam">Đồ nam</label>
                        </div>
                        <div className="form-check">
                            <input className="form-check-input" type="checkbox" id="nu" />
                            <label className="form-check-label" htmlFor="nu">Đồ nữ</label>
                        </div>
                        <div className="form-check">
                            <input className="form-check-input" type="checkbox" id="treem" />
                            <label className="form-check-label" htmlFor="treem">Trẻ em</label>
                        </div>
                    </div>
                </div>

                {/* Danh sách sản phẩm */}
                <div className="col-md-9">
                    <h4 className="mb-4">Có {products.length} sản phẩm được tìm thấy</h4>
                    <div className="row">
                        {products.map((product) => (
                            <div key={product.id} className="col-md-4 mb-4">
                                <div className="card h-100 shadow-sm">
                                    <img
                                        src={product.image}
                                        className="card-img-top"
                                        alt={product.name}
                                        style={{ height: "200px", objectFit: "cover" }}
                                    />
                                    <div className="card-body text-center">
                                        <h5 className="card-title">{product.name}</h5>
                                        <p className="card-text text-primary fw-bold">
                                            {product.price.toLocaleString()}₫
                                        </p>
                                        <button
                                            className="btn btn-success w-100"
                                            onClick={() => addToCart(product)}
                                        >
                                            Thêm vào giỏ hàng
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default HomePage;
